mapper.select:
SELECT  FROM review_repractice WHERE owner_id=#{owner}
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

SELECT owner_id,repractice_id,source_id,action_id,action_revision,position_index AS position,snapshot_json
FROM review_repractice_source WHERE owner_id=#{owner} AND repractice_id=#{repracticeId}
ORDER BY position_index

SELECT  FROM review_source_judgment WHERE owner_id=#{owner} AND source_id=#{sourceId}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}
